const API_URL = 'http://localhost:8000/books'

async function handleResponse(response) {
  if (!response.ok) {
    throw new Error(`Request failed with status ${response.status}`)
  }

  return response.json()
}

export async function listBooks() {
  const response = await fetch(API_URL)
  return handleResponse(response)
}

export async function createBook(book) {
  const response = await fetch(API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(book),
  })

  return handleResponse(response)
}

export async function updateBookStatus(id, status) {
  const response = await fetch(`${API_URL}/${id}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ status }),
  })

  return handleResponse(response)
}

import { useEffect, useState } from 'react'
import { listBooks } from '../api'

function BookList() {
  const [books, setBooks] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    let ignore = false

    async function loadBooks() {
      try {
        const data = await listBooks()
        if (!ignore) {
          setBooks(data)
        }
      } catch (err) {
        if (!ignore) {
          setError(err.message)
        }
      } finally {
        if (!ignore) {
          setLoading(false)
        }
      }
    }

    loadBooks()

    return () => {
      ignore = true
    }
  }, [])

  if (loading) {
    return <p>Caricamento libri...</p>
  }

  if (error) {
    return <p>Errore: {error}</p>
  }

  if (books.length === 0) {
    return <p>Nessun libro presente.</p>
  }

  return (
    <section>
      <h2>Lista libri</h2>
      <ul>
        {books.map((book) => (
          <li key={book.id}>
            <strong>{book.title}</strong> di {book.author} — {book.status}
          </li>
        ))}
      </ul>
    </section>
  )
}

export default BookList

import { useState } from 'react'
import { createBook } from '../api'

function BookForm() {
  const [title, setTitle] = useState('')
  const [author, setAuthor] = useState('')
  const [status, setStatus] = useState('to-read')
  const [message, setMessage] = useState('')

  async function handleSubmit(event) {
    event.preventDefault()
    setMessage('')

    try {
      await createBook({ title, author, status })
      setTitle('')
      setAuthor('')
      setStatus('to-read')
      setMessage('Libro aggiunto con successo.')
    } catch (err) {
      setMessage(`Errore: ${err.message}`)
    }
  }

  return (
    <section>
      <h2>Aggiungi libro</h2>
      <form onSubmit={handleSubmit}>
        <label>
          Titolo
          <input
            type="text"
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            required
          />
        </label>

        <label>
          Autore
          <input
            type="text"
            value={author}
            onChange={(event) => setAuthor(event.target.value)}
            required
          />
        </label>

        <label>
          Stato
          <select
            value={status}
            onChange={(event) => setStatus(event.target.value)}
          >
            <option value="to-read">Da leggere</option>
            <option value="reading">In lettura</option>
            <option value="done">Letto</option>
          </select>
        </label>

        <button type="submit">Salva</button>
      </form>
      {message && <p>{message}</p>}
    </section>
  )
}

export default BookForm

import './App.css'
import BookForm from './components/BookForm'
import BookList from './components/BookList'

function App() {
  return (
    <main>
      <h1>BookTrack</h1>
      <BookForm />
      <BookList />
    </main>
  )
}

export default App
